import pandas as pd
import numpy as np
import requests
import time
import glob
import os
import json as _json
from datetime import datetime, timezone, timedelta
from functionality.log_writer import log_ag_pick_closure

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

BASE = 'https://api.massive.com'

API_KEY = (
    (CREDENTIALS.get('MASSIVE_API_KEY') or '').strip()
    or (CREDENTIALS.get('POLYGON_API_KEY') or '').strip()
)

# Resolve current account size + paths from settings (Wave 2 of OEB).
PICKS_DIR = 'indexes/IMMUTABLE/ag_picks'
CLOSURES_DIR = 'indexes/IMMUTABLE/ag_picks_closures'
CURRENT_ACCOUNT_SIZE = 1000.0
try:
    from global_settings import get_settings
    _s = get_settings()
    CURRENT_ACCOUNT_SIZE = float(_s.get('current_account_size_usd') or 1000.0)
    PICKS_DIR = str(_s.immutable_subdir('ag_picks'))
    CLOSURES_DIR = str(_s.immutable_subdir('ag_picks_closures'))
except Exception:
    pass

ALERT_GROUP = 'options_edge_brief'

OUTPUT_COLUMNS = [
    'idea_id', 'instrument_id', 'outcome', 'trigger_rule',
    'entry_price', 'exit_price', 'pnl_per_contract_usd',
    'pnl_pct_vs_max_loss', 'days_held', 'closure_quality',
    'fits_account_at_close', '_epoch',
]


def _emit_info_row(detail, count_open=0, count_closed=0):
    return pd.DataFrame([{
        'idea_id': 'INFO', 'instrument_id': '',
        'outcome': 'noop', 'trigger_rule': '',
        'entry_price': None, 'exit_price': None,
        'pnl_per_contract_usd': None, 'pnl_pct_vs_max_loss': None,
        'days_held': None, 'closure_quality': '',
        'fits_account_at_close': None,
        'detail': detail[:1500],
        'open_picks_seen': count_open, 'closures_written': count_closed,
        '_epoch': now_epoch,
    }], columns=OUTPUT_COLUMNS + ['detail', 'open_picks_seen', 'closures_written'])


if not API_KEY:
    df = _emit_info_row(
        'MASSIVE_API_KEY (or POLYGON_API_KEY) credential is not set. Required '
        'for the pick tracker. Add it in Settings > Global Credentials.'
    )
    GENERATE_RESULTS(df)
else:
    pick_files = sorted(
        glob.glob(f'{PICKS_DIR}/*.parquet'),
        key=os.path.getmtime,
        reverse=True,
    )
    if not pick_files:
        df = _emit_info_row(
            f'No picks at {PICKS_DIR}. Day-1 normal: the OEB has not '
            f'dispatched yet OR the migration from logs/ag_picks/ has '
            f'not run on this engine startup.'
        )
        GENERATE_RESULTS(df)
    else:
        # Load picks (most recent 100 files). At ~1-2 files/dispatch ×
        # 2 dispatches/day × 5 weekdays = ~10-20 files/week, 100 files
        # covers ~5-10 weeks - comfortably longer than the longest pick
        # DTE (60 days) so no open pick is silently aged out of the
        # tracker's view. Bumped from 30 on 2026-04-27 audit.
        pick_frames = []
        for p in pick_files[:100]:
            try:
                f = pd.read_parquet(p)
                if f is not None and not f.empty:
                    pick_frames.append(f)
            except Exception:
                continue
        picks_df = pd.concat(pick_frames, ignore_index=True) if pick_frames else pd.DataFrame()

        if 'alert_group' in picks_df.columns:
            picks_df = picks_df[picks_df['alert_group'] == ALERT_GROUP]

        # Load closures to identify already-closed picks
        closure_files = sorted(glob.glob(f'{CLOSURES_DIR}/*.parquet'))
        closed_idea_ids = set()
        for p in closure_files:
            try:
                cf = pd.read_parquet(p)
                if cf is not None and not cf.empty and 'idea_id' in cf.columns:
                    for v in cf['idea_id'].tolist():
                        if v:
                            closed_idea_ids.add(str(v))
            except Exception:
                continue

        # Open picks: not in closed set; dedupe to most recent entry per idea_id
        if 'idea_id' in picks_df.columns and not picks_df.empty:
            picks_df = picks_df[~picks_df['idea_id'].astype(str).isin(closed_idea_ids)]
            if '_epoch' in picks_df.columns:
                picks_df = picks_df.sort_values('_epoch', ascending=False)
            picks_df = picks_df.drop_duplicates(subset=['idea_id'], keep='first')

        if picks_df.empty:
            df = _emit_info_row('No open OEB picks to track.', count_open=0, count_closed=0)
            GENERATE_RESULTS(df)
        else:
            rows = []
            errors = []
            auth_failed = False
            closed_count = 0
            open_count = len(picks_df)

            def _massive_get(url, params=None):
                params = dict(params or {})
                params['apiKey'] = API_KEY
                last_exc = None
                for attempt in range(2):
                    try:
                        r = requests.get(url, params=params, timeout=15)
                        if r.status_code in (401, 403):
                            raise RuntimeError(f'Massive auth failure: {r.status_code}')
                        if r.status_code == 429:
                            time.sleep(4.0)
                            continue
                        if r.status_code == 404:
                            return {}
                        r.raise_for_status()
                        return r.json() or {}
                    except requests.exceptions.RequestException as exc:
                        last_exc = exc
                        if attempt == 0:
                            time.sleep(2.0)
                            continue
                        raise
                if last_exc:
                    raise last_exc
                return {}

            def _safe_float(v):
                if v is None:
                    return None
                try:
                    f = float(v)
                except Exception:
                    return None
                if f != f:
                    return None
                return f

            def _leg_mid(contract):
                lq = contract.get('last_quote') or {}
                bid = _safe_float(lq.get('bid'))
                ask = _safe_float(lq.get('ask'))
                if bid is not None and ask is not None and bid > 0 and ask >= bid:
                    return (bid + ask) / 2.0, bid, ask
                day = contract.get('day') or {}
                close = _safe_float(day.get('close'))
                if close is not None and close > 0:
                    return close, None, None
                vwap = _safe_float(day.get('vwap'))
                if vwap is not None and vwap > 0:
                    return vwap, None, None
                return None, None, None

            def _ticker_from_opra(symbol):
                # OPRA: O:NVDA260620P00115000 -> NVDA
                if not symbol or not symbol.startswith('O:'):
                    return ''
                body = symbol[2:]
                for i, c in enumerate(body):
                    if c.isdigit():
                        return body[:i]
                return ''

            for _, pick in picks_df.iterrows():
                if auth_failed:
                    break
                idea_id = str(pick.get('idea_id') or '')
                if not idea_id:
                    continue

                legs_raw = pick.get('option_legs_json')
                if pd.isna(legs_raw) or not legs_raw:
                    continue
                try:
                    legs = _json.loads(legs_raw)
                    if not isinstance(legs, list) or not legs:
                        continue
                except Exception as exc:
                    errors.append(f'{idea_id}:bad_legs_json:{exc}')
                    continue

                entry_price = _safe_float(pick.get('entry_price'))
                stop_loss = _safe_float(pick.get('stop_loss_price'))
                take_profit = _safe_float(pick.get('take_profit_price'))
                try:
                    suggested_sell_epoch = (
                        int(pick.get('suggested_sell_epoch'))
                        if pick.get('suggested_sell_epoch') is not None
                        else None
                    )
                except Exception:
                    suggested_sell_epoch = None
                option_max_loss = _safe_float(pick.get('option_max_loss_usd'))
                option_max_profit = _safe_float(pick.get('option_max_profit_usd'))
                account_size_floor = _safe_float(pick.get('account_size_floor_usd'))
                fits_at_entry = (
                    bool(account_size_floor and account_size_floor <= CURRENT_ACCOUNT_SIZE)
                    if account_size_floor is not None else None
                )
                fits_at_close = fits_at_entry
                try:
                    entry_epoch = (
                        int(pick.get('_epoch'))
                        if pick.get('_epoch') is not None else None
                    )
                except Exception:
                    entry_epoch = None

                # Process each leg
                leg_prices = []
                net_now = 0.0
                any_missing = False
                latest_expiration = None
                for leg in legs:
                    contract_symbol = str(leg.get('contract_symbol') or '')
                    action = str(leg.get('action') or '').upper()
                    qty = int(leg.get('qty') or 1)
                    expiration_str = str(leg.get('expiration') or '')
                    if expiration_str:
                        try:
                            exp_dt = datetime.strptime(
                                expiration_str, '%Y-%m-%d',
                            ).replace(tzinfo=timezone.utc)
                            if latest_expiration is None or exp_dt > latest_expiration:
                                latest_expiration = exp_dt
                        except Exception:
                            pass

                    ticker = _ticker_from_opra(contract_symbol)
                    if not contract_symbol or not ticker:
                        any_missing = True
                        leg_prices.append({
                            'contract_symbol': contract_symbol, 'mid': None,
                            'bid': None, 'ask': None, 'reason': 'no_symbol',
                        })
                        continue

                    try:
                        url = f'{BASE}/v3/snapshot/options/{ticker}/{contract_symbol}'
                        payload = _massive_get(url)
                    except RuntimeError:
                        errors.append(f'{idea_id}:auth_failure')
                        auth_failed = True
                        any_missing = True
                        leg_prices.append({
                            'contract_symbol': contract_symbol, 'mid': None,
                            'bid': None, 'ask': None, 'reason': 'auth',
                        })
                        break
                    except Exception as exc:
                        any_missing = True
                        leg_prices.append({
                            'contract_symbol': contract_symbol, 'mid': None,
                            'bid': None, 'ask': None, 'reason': str(exc)[:50],
                        })
                        continue

                    contract = payload.get('results') or payload.get('result') or {}
                    if not contract or not isinstance(contract, dict):
                        any_missing = True
                        leg_prices.append({
                            'contract_symbol': contract_symbol, 'mid': None,
                            'bid': None, 'ask': None, 'reason': 'no_data',
                        })
                        continue
                    mid, bid, ask = _leg_mid(contract)
                    if mid is None:
                        any_missing = True
                        leg_prices.append({
                            'contract_symbol': contract_symbol, 'mid': None,
                            'bid': None, 'ask': None, 'reason': 'no_price',
                        })
                        continue
                    leg_prices.append({
                        'contract_symbol': contract_symbol,
                        'mid': round(mid, 4),
                        'bid': round(bid, 4) if bid is not None else None,
                        'ask': round(ask, 4) if ask is not None else None,
                    })
                    sign = 1.0 if action == 'BUY' else -1.0
                    net_now += mid * sign * qty
                    time.sleep(0.2)

                # Determine outcome - order matters: expiration first, then time stop, then price triggers.
                outcome = None
                trigger_rule = None
                exit_price = None
                closure_quality = 'clean'

                if latest_expiration and now > latest_expiration:
                    outcome = 'expired'
                    trigger_rule = 'expiration'
                    exit_price = net_now if not any_missing else 0.0
                    closure_quality = 'expired_otm' if (exit_price or 0.0) <= 0.0 else 'expired_itm'
                elif suggested_sell_epoch and now_epoch >= suggested_sell_epoch and not any_missing:
                    outcome = 'time_exit'
                    trigger_rule = 'time_stop'
                    exit_price = net_now
                elif not any_missing and entry_price is not None:
                    if stop_loss is not None and net_now <= stop_loss and entry_price > 0:
                        # Long premium hitting stop
                        outcome = 'lost'
                        trigger_rule = 'stop_loss_hit'
                        exit_price = stop_loss
                    elif take_profit is not None and net_now >= take_profit and entry_price > 0:
                        # Long premium hitting take
                        outcome = 'won'
                        trigger_rule = 'take_profit_hit'
                        exit_price = take_profit
                    elif stop_loss is not None and entry_price < 0 and net_now <= stop_loss:
                        # Short premium hitting stop (more negative net)
                        outcome = 'lost'
                        trigger_rule = 'stop_loss_hit'
                        exit_price = stop_loss
                    elif take_profit is not None and entry_price < 0 and net_now >= take_profit:
                        # Short premium hitting take
                        outcome = 'won'
                        trigger_rule = 'take_profit_hit'
                        exit_price = take_profit

                if outcome is None:
                    continue  # still open

                # P&L per 1 contract: signed entry & exit make this work for both directions.
                if exit_price is None or entry_price is None:
                    pnl_per_contract = None
                else:
                    pnl_per_contract = round((exit_price - entry_price) * 100.0, 2)

                if pnl_per_contract is not None and option_max_loss and option_max_loss > 0:
                    if pnl_per_contract >= 0 and option_max_profit and option_max_profit > 0:
                        pnl_pct = round(pnl_per_contract / option_max_profit * 100.0, 2)
                    else:
                        pnl_pct = round(pnl_per_contract / option_max_loss * 100.0, 2)
                else:
                    pnl_pct = None

                days_held = round((now_epoch - entry_epoch) / 86400.0, 2) if entry_epoch else 0.0
                if any_missing and outcome != 'expired':
                    closure_quality = 'illiquid'

                instrument_type = str(pick.get('instrument_type') or 'option')
                instrument_id = str(pick.get('instrument_id') or '')

                try:
                    log_ag_pick_closure(
                        alert_group=ALERT_GROUP,
                        idea_id=idea_id,
                        instrument_type=instrument_type,
                        instrument_id=instrument_id,
                        outcome=outcome,
                        trigger_rule=trigger_rule,
                        entry_price=entry_price,
                        exit_price=exit_price,
                        exit_epoch=now_epoch,
                        pnl_per_contract_usd=pnl_per_contract or 0.0,
                        pnl_pct_vs_max_loss=pnl_pct or 0.0,
                        days_held=days_held,
                        leg_prices_at_close_json=_json.dumps(leg_prices),
                        closure_quality=closure_quality,
                        account_size_floor_usd=account_size_floor,
                        fits_account_at_entry=fits_at_entry,
                        current_account_size_usd_at_close=CURRENT_ACCOUNT_SIZE,
                        fits_account_at_close=fits_at_close,
                    )
                    closed_count += 1
                    rows.append({
                        'idea_id': idea_id,
                        'instrument_id': instrument_id,
                        'outcome': outcome,
                        'trigger_rule': trigger_rule,
                        'entry_price': entry_price,
                        'exit_price': exit_price,
                        'pnl_per_contract_usd': pnl_per_contract,
                        'pnl_pct_vs_max_loss': pnl_pct,
                        'days_held': days_held,
                        'closure_quality': closure_quality,
                        'fits_account_at_close': fits_at_close,
                        '_epoch': now_epoch,
                    })
                except Exception as exc:
                    errors.append(f'{idea_id}:write_failed:{exc}')

            # Force-flush the log writer so closures land on disk before we exit
            try:
                from functionality.log_writer import flush_all
                flush_all()
            except Exception:
                pass

            if rows:
                df = pd.DataFrame(rows, columns=OUTPUT_COLUMNS)
            else:
                detail = (
                    f'{open_count} open pick(s) checked, none hit an exit rule. '
                    f'Errors: {"; ".join(errors[:5]) if errors else "none"}'
                )
                df = _emit_info_row(detail, count_open=open_count, count_closed=0)
            GENERATE_RESULTS(df)
